# hypothesis: A Final attribute declared with a widened union type keeps that union when read through a subclass, an instance, or the class, and reassigning it is rejected by checkers while CPython still runs it.
from typing import ClassVar, Final, reveal_type


class Base:
    code: Final[int | str | None] = 3
    scale: ClassVar[float] = 1.5


class Child(Base):
    pass


class Holder:
    level: Final[int | None] = None


def show(c: Child) -> str:
    reveal_type(c.code)
    reveal_type(Child.scale)
    return f'{c.code} {Child.scale}'


def try_reassign(h: Holder) -> None:
    try:
        h.level = 5  # expect-error
    except TypeError:
        pass


h = Holder()
print(show(Child()))
try_reassign(h)
reveal_type(h.level)
print(h.level)
